for filename, (title, description, main) in pages.items():
    key = filename.removesuffix('.html')
    marked = HEADER.replace(f'href="{filename}"', f'href="{filename}" aria-current="page"')
    preview_header = marked if SHOW_HEADER else '<a class="sxa-skip" href="#sxa-main">Skip to content</a>'
    preview_footer = (HOME_FOOTER if filename == 'index.html' else FOOTER) if SHOW_FOOTER else ''
    preview_class = 'sxa-site' if SHOW_HEADER else 'sxa-site sxa-preview-without-chrome'
    document = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{description}"><link rel="stylesheet" href="site.css"><script defer src="site.js"></script></head>
<body><div class="{preview_class}">{preview_header}\n{main}\n{preview_footer}</div></body></html>\n'''
    (BASE / filename).write_text(document, encoding='utf-8')
    # Each WordPress module gets a scope wrapper. Internal links point at site URLs.
    def to_wp(html):
        routes = {
            'index.html': 'https://scale-xpert.com/',
            'about.html': 'https://scale-xpert.com/about-us/',
            'services.html': 'https://scale-xpert.com/services/',
            'pricing.html': 'https://scale-xpert.com/pricing/',
            'community.html': 'https://scale-xpert.com/community/',
            'contact.html': 'https://scale-xpert.com/contact/',
            'privacy.html': 'https://scale-xpert.com/privacy-policy/',
        }
        for old, new in routes.items():
            html = html.replace(f'href="{old}', f'href="{new}')
        html = html.replace('src="assets/scale-xpert-logo.png"', 'src="https://scale-xpert.com/wp-content/uploads/2026/01/Desing-website-SX-6-e1769851551100.png"')
        html = html.replace('src="assets/gsc-client-01.webp"', 'src="https://scale-xpert.com/wp-content/uploads/2026/05/result-analytic-heaven-guardian.webp"')
        html = html.replace('data-sxa-open-image="assets/gsc-client-01.webp"', 'data-sxa-open-image="https://scale-xpert.com/wp-content/uploads/2026/05/result-analytic-heaven-guardian.webp"')
        return html
    (SNIPPETS / f'{key}-main.html').write_text('<div class="sxa-site">\n' + to_wp(main) + '\n</div>\n', encoding='utf-8')

(SNIPPETS / 'global-header.html').write_text('<div class="sxa-site">\n' + to_wp(HEADER) + '\n</div>\n', encoding='utf-8')
(SNIPPETS / 'global-footer.html').write_text('<div class="sxa-site">\n' + to_wp(FOOTER) + '\n</div>\n', encoding='utf-8')
